// Collect headlines from Alpha Vantage + RSS into one de-duped batch.
function headlinesFrom(j) {
  if (j && Array.isArray(j.feed)) {
    // Alpha Vantage NEWS_SENTIMENT shape
    return j.feed.map(a => ({ title: a.title, source: a.source, publishedAt: a.time_published }));
  }
  if (j && j.title) {
    // RSS Read item shape
    return [{ title: j.title, source: j.creator || j.source || 'RSS', publishedAt: j.isoDate || j.pubDate || null }];
  }
  return [];
}

// FX-relevant filter: keep items mentioning a currency / central-bank term.
const KEEP = /\b(fed|fomc|ecb|boj|boe|rate|inflation|cpi|nfp|payroll|gdp|dollar|euro|yen|gold|bitcoin|treasury|powell|lagarde|usd|eur|jpy|gbp|xau|btc)\b/i;

const seen = new Set();
const headlines = [];
for (const item of $input.all()) {
  for (const h of headlinesFrom(item.json)) {
    const t = String(h.title || '').trim();
    if (!t || seen.has(t)) continue;
    if (!KEEP.test(t)) continue;
    seen.add(t);
    headlines.push({ title: t.slice(0, 300), source: h.source || null, publishedAt: h.publishedAt || null });
  }
}

if (headlines.length === 0) return []; // nothing relevant — stop the branch
return [{ json: { headlines: headlines.slice(0, 25) } }];

// Build a NewsEvent upsert from the AI's structured summary.
function esc(v) {
  if (v === null || v === undefined || v === '') return 'NULL';
  return "'" + String(v).replace(/'/g, "''") + "'";
}
function hashId(s) {
  let h = 5381;
  for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) >>> 0;
  return 'news_' + h.toString(16);
}

const ai = $json || {};
const now = new Date();
const scheduledAt = now.toISOString().slice(0, 19).replace('T', ' '); // naive UTC
// Digests are commentary stamped scheduledAt=now, not scheduled releases -
// HIGH would trip the risk engine's after-release blackout on every run.
const impact = ['LOW', 'MEDIUM'].includes(ai.impact) ? ai.impact : 'MEDIUM';
const currency = String(ai.currency || 'USD').trim().toUpperCase().slice(0, 10) || 'USD';
const summary = String(ai.summary || '').slice(0, 1000);
if (!summary) return [];
const title = ('News digest: ' + summary).slice(0, 200);
const id = hashId(title + '|' + scheduledAt);

const query =
  'INSERT INTO "NewsEvent" ("id","title","impact","currency","scheduledAt","aiSummary","createdAt") VALUES (' +
  [esc(id), esc(title), esc(impact), esc(currency), esc(scheduledAt), esc(summary)].join(',') +
  ', now()) ON CONFLICT ("title","scheduledAt") DO UPDATE SET "aiSummary"=EXCLUDED."aiSummary","impact"=EXCLUDED."impact";';
return [{ json: { query } }];
